solution.python:
def coin_change(coins: list[int], amount: int) -> int:
    unreachable = amount + 1
    dp = [unreachable] * (amount + 1)
    dp[0] = 0

    for subtotal in range(1, amount + 1):
        for coin in coins:
            if coin <= subtotal:
                # Try this denomination as the last coin.
                dp[subtotal] = min(dp[subtotal], dp[subtotal - coin] + 1)

    return -1 if dp[amount] == unreachable else dp[amount]

solution.java:
import java.util.Arrays;

class Solution {
    public int coinChange(int[] coins, int amount) {
        int unreachable = amount + 1;
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, unreachable);
        dp[0] = 0;

        for (int subtotal = 1; subtotal <= amount; subtotal++) {
            for (int coin : coins) {
                if (coin <= subtotal) {
                    // Try this denomination as the last coin.
                    dp[subtotal] = Math.min(
                        dp[subtotal], dp[subtotal - coin] + 1
                    );
                }
            }
        }
        return dp[amount] == unreachable ? -1 : dp[amount];
    }
}

solution.javascript:
function coinChange(coins, amount) {
    const unreachable = amount + 1;
    const dp = new Array(amount + 1).fill(unreachable);
    dp[0] = 0;

    for (let subtotal = 1; subtotal <= amount; subtotal++) {
        for (const coin of coins) {
            if (coin <= subtotal) {
                // Try this denomination as the last coin.
                dp[subtotal] = Math.min(
                    dp[subtotal], dp[subtotal - coin] + 1
                );
            }
        }
    }
    return dp[amount] === unreachable ? -1 : dp[amount];
}
